import { GetObjectCommand, HeadObjectCommand } from '@aws-sdk/client-s3';
import { NextFunction, Request, Response } from 'express';
import { Readable } from 'node:stream';

import { getS3 } from '../infrastructure/s3';
import { AudioTrack } from '../models/audioTrack';
import type { MotionPreviewActive } from '../models/motionPreview';
import { isPublicCatalogVisibility } from '../services/catalog/catalogVisibilityService';
import {
    createMediaAbortContext,
    mediaAuthorizationTimeoutMs,
    pipeMediaStream,
    shouldHonorRange
} from '../services/media/mediaDeliveryService';
import { isMotionPreviewRevision, publicMotionPreviewForTrack } from '../services/media/motionPreviewService';
import { logCatalogFailure } from './catalogDiagnostics';
import { resolveMediaTrackByteResponse } from './mediaTrackController';

/** Deterministic boundaries for gate and storage tests. */
export interface MotionPreviewResolverDependencies {
    findReadyTrack: (mediaTrackId: string, maxTimeMS?: number) => Promise<any | null>;
    headObject: (
        params: { Bucket: string; Key: string; IfMatch: string; VersionId?: string },
        abortSignal: AbortSignal
    ) => Promise<{ ContentLength?: number; ETag?: string; VersionId?: string }>;
}

const defaultDependencies: MotionPreviewResolverDependencies = {
    findReadyTrack: (mediaTrackId, maxTimeMS) => AudioTrack.findReadyPublicById(mediaTrackId, maxTimeMS),
    headObject: (params, abortSignal) => getS3().send(new HeadObjectCommand(params), { abortSignal })
};

/** The preview a public request may see: a ready, visible Video track's current, bound preview. */
const visiblePreview = (track: any) => (
    track && isPublicCatalogVisibility(track) ? publicMotionPreviewForTrack(track) : null
);

const samePreview = (left: MotionPreviewActive | null, right: MotionPreviewActive) => Boolean(left
    && left.revision === right.revision
    && left.s3Key === right.s3Key
    && left.etag === right.etag
    && left.versionId === right.versionId);

/**
 * Resolves one public motion preview. Every gate failure is a bare not-found before any storage
 * call; storage metadata must match the recorded object exactly, and the gate is re-applied after it.
 */
export const resolveMotionPreview = async (
    mediaTrackId: string,
    revision: string | undefined,
    abortSignal: AbortSignal,
    ifNoneMatch: string | undefined,
    overrides: Partial<MotionPreviewResolverDependencies> = {}
) => {
    const dependencies = { ...defaultDependencies, ...overrides };
    const normalizedId = String(mediaTrackId ?? '').trim().toLowerCase();
    if (!/^[0-9a-f]{24}$/.test(normalizedId)) return { status: 'notFound' as const };
    const preview = visiblePreview(await dependencies.findReadyTrack(normalizedId));
    if (!preview || (revision !== undefined && preview.revision !== revision)) return { status: 'notFound' as const };
    // A revalidation needs no storage I/O: the recorded strong ETag identifies the exact bytes.
    if (ifNoneMatch !== undefined && ifNoneMatch === preview.etag) return { status: 'notModified' as const, preview };
    const params = {
        Bucket: process.env.S3_BUCKET_NAME!,
        Key: preview.s3Key,
        IfMatch: preview.etag,
        ...(preview.versionId ? { VersionId: preview.versionId } : {})
    };
    const metadata = await dependencies.headObject(params, abortSignal);
    if (metadata.ContentLength !== preview.byteLength || metadata.ETag !== preview.etag
        || (preview.versionId && metadata.VersionId !== preview.versionId)) return { status: 'notFound' as const };
    if (!samePreview(visiblePreview(await dependencies.findReadyTrack(normalizedId)), preview)) {
        return { status: 'notFound' as const };
    }
    const authorize = async () => samePreview(
        visiblePreview(await dependencies.findReadyTrack(normalizedId, mediaAuthorizationTimeoutMs)),
        preview
    );
    return { status: 'ready' as const, preview, params, authorize };
};

const s3ErrorStatus = (error: any) => {
    const status = Number(error?.$metadata?.httpStatusCode ?? 0);
    return status === 404 || status === 412 ? 404 : 502;
};

const setPreviewHeaders = (res: Response, preview: MotionPreviewActive, contentLength?: number) => {
    res.setHeader('Accept-Ranges', 'bytes');
    res.setHeader('Content-Type', 'video/mp4');
    if (contentLength !== undefined) res.setHeader('Content-Length', contentLength);
    // Every reuse revalidates, so a revoked or replaced preview stops being served at once.
    res.setHeader('Cache-Control', 'private, no-cache, no-transform');
    res.setHeader('ETag', preview.etag);
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Accel-Buffering', 'no');
};

const requestedRevision = (req: Request) => {
    const keys = Object.keys(req.query);
    if (keys.some((key) => key !== 'revision')) return { valid: false as const };
    const revision = req.query.revision;
    if (revision === undefined) return { valid: true as const, revision: undefined };
    return isMotionPreviewRevision(revision) ? { valid: true as const, revision } : { valid: false as const };
};

const ifNoneMatchOf = (req: Request) => (
    typeof req.headers['if-none-match'] === 'string' ? req.headers['if-none-match'] : undefined
);

export const headMotionPreview = async (req: Request, res: Response, _next: NextFunction) => {
    const query = requestedRevision(req);
    if (!query.valid) return res.status(400).end();
    const context = createMediaAbortContext(req, res);
    try {
        const resolved = await resolveMotionPreview(req.params.mediaTrackId, query.revision, context.signal, ifNoneMatchOf(req));
        if (resolved.status === 'notFound') return res.status(404).end();
        setPreviewHeaders(res, resolved.preview, resolved.status === 'ready' ? resolved.preview.byteLength : undefined);
        return res.status(resolved.status === 'notModified' ? 304 : 200).end();
    } catch (error: any) {
        if (context.aborted || error?.name === 'AbortError') return;
        const status = s3ErrorStatus(error);
        if (status >= 500) logCatalogFailure(res, 'media_probe_failed', error);
        return res.status(status).end();
    } finally {
        context.cleanup();
    }
};

export const streamMotionPreview = async (req: Request, res: Response, _next: NextFunction) => {
    const query = requestedRevision(req);
    if (!query.valid) return res.status(400).end();
    const context = createMediaAbortContext(req, res);
    try {
        const resolved = await resolveMotionPreview(req.params.mediaTrackId, query.revision, context.signal, ifNoneMatchOf(req));
        if (resolved.status === 'notFound') return res.status(404).end();
        if (resolved.status === 'notModified') {
            setPreviewHeaders(res, resolved.preview);
            return res.status(304).end();
        }
        const { preview } = resolved;
        const requestedRange = shouldHonorRange(
            typeof req.headers['if-range'] === 'string' ? req.headers['if-range'] : undefined,
            preview.etag
        ) ? req.headers.range : undefined;
        const byteResponse = resolveMediaTrackByteResponse(requestedRange, preview.byteLength);
        if (byteResponse.status === 416) {
            res.setHeader('Accept-Ranges', 'bytes');
            res.setHeader('Content-Range', byteResponse.contentRange);
            return res.status(416).end();
        }
        const { start, end } = byteResponse;
        const object = await getS3().send(new GetObjectCommand({
            ...resolved.params,
            Range: byteResponse.status === 206 ? `bytes=${start}-${end}` : undefined
        }), { abortSignal: context.signal });
        const stream = object.Body as unknown as Readable | undefined;
        if (!stream || typeof stream.pipe !== 'function') throw new Error('S3 preview body is not a readable stream.');
        if (object.ETag !== preview.etag || object.ContentLength !== end - start + 1
            || (preview.versionId && object.VersionId !== preview.versionId)) {
            stream.destroy();
            return res.status(404).end();
        }
        await pipeMediaStream(req, res, stream, context, {
            authorize: resolved.authorize,
            onAuthorized: () => {
                res.status(byteResponse.status);
                if (byteResponse.status === 206) res.setHeader('Content-Range', byteResponse.contentRange);
                setPreviewHeaders(res, preview, end - start + 1);
                res.setHeader('Content-Disposition', 'inline');
            }
        });
    } catch (error: any) {
        if (context.aborted || error?.name === 'AbortError') return;
        logCatalogFailure(res, 'media_stream_failed', error);
        if (!res.headersSent) return res.status(s3ErrorStatus(error)).end();
        res.destroy(error instanceof Error ? error : undefined);
    } finally {
        context.cleanup();
    }
};
